/*
Theme Name: Careful Shopper Twenty Twenty-Five
Template: twentytwentyfive
Version: 1.0.0
*/
/* Careful Shopper source-aligned child theme. */
:root{--g:#006633;--b:#0033FF;--brown:#663300;--white:#FFFFFF;--text:#0F1111;--black:#000000;--beige:#F6F2EA;--mint:#EAF3EE;--yellow:#FDF6D8;--gold:#CC9900;--line:#DDDDDD}
*{box-sizing:border-box;min-width:0}html,body,.wp-site-blocks{max-width:100%}html{font-size:100%}
body{margin:0;background:var(--white);color:var(--text);font:400 1rem/1.6 Verdana,Geneva,Arial,sans-serif}
img,iframe,video,svg{max-width:100%}a{color:var(--b);font-weight:700;text-decoration:underline;text-underline-offset:.12em;cursor:pointer}a:hover{text-decoration-thickness:.125rem}
a:focus-visible,button:focus-visible{outline:.2rem solid var(--g);outline-offset:.2rem}button{font:inherit;cursor:pointer}
main,.wp-site-blocks main{width:min(60rem,calc(100% - 2rem));max-width:100%;margin:2rem auto 3rem}
.zone{position:relative;margin:0 0 1.5rem;padding:2rem;border:.0625rem solid var(--line);border-radius:.75rem;background:var(--white);box-shadow:none}
.site-header{padding:1rem;background:var(--white);border-bottom:.125rem solid var(--line)}.header-inner{width:min(60rem,100%);margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:1rem}
.brand{display:flex;flex:0 0 auto;align-items:center;gap:.75rem;color:var(--g);text-decoration:none}.brand-mark{display:grid;place-items:center;flex:0 0 3rem;width:3rem;height:3rem;border:.0625rem solid var(--g);border-radius:.5rem;background:var(--mint);color:var(--g);font-size:1rem;font-weight:700}
.brand-copy{display:flex;flex-direction:column;line-height:1.25}.brand-name{color:var(--g);font-size:1.4rem;font-weight:700;text-decoration:none}.tagline{margin-top:.25rem;color:var(--text);font-size:1rem;font-weight:400}
.desktop-nav{display:flex;flex:0 0 auto;flex-wrap:nowrap;align-items:center;justify-content:flex-end;gap:1.5rem;margin-left:auto;white-space:nowrap}.desktop-nav a,.mobile-nav a,.nav-unavailable{color:var(--b);font-size:1rem;font-weight:700;text-decoration:underline}.nav-unavailable{cursor:default}
.menu-button{display:none;min-height:3rem;padding:.75rem 1rem;border:0;border-radius:.5rem;background:var(--brown);color:var(--white);font-size:1rem;font-weight:700}.menu-button:hover{background:var(--brown);color:var(--white)}
.mobile-nav{display:none;width:min(60rem,calc(100% - 2rem));margin:.75rem auto 0;padding:1rem;border:.0625rem solid var(--line);border-radius:.75rem;background:var(--white)}.mobile-nav.open{display:flex;flex-direction:column;align-items:stretch;gap:1rem}.mobile-nav a,.mobile-nav .nav-unavailable{display:flex;align-items:center;min-height:3rem;padding:.5rem 0;border-bottom:.0625rem solid var(--line)}
.hero{padding:2rem;border:0;border-radius:.75rem;background:var(--g);color:var(--white)}.hero>*{position:relative;z-index:1;max-width:52rem}.hero h1{margin:.5rem 0 1rem;color:var(--white);font-size:1.4rem;line-height:1.35;font-weight:700}.hero a,.hero .breadcrumb,.hero .byline,.hero .short-answer{color:var(--white)}.breadcrumb{margin:0 0 .75rem}.byline{margin-bottom:.875rem}.short-answer{margin:0}
.disclosure{padding:1.25rem;border:.125rem solid var(--gold);border-radius:.75rem;background:var(--yellow);color:var(--black);font-size:1.333rem;font-weight:400;font-style:normal;line-height:1.5}
h2{margin:0 0 1rem;color:var(--g);font-size:1.2rem;line-height:1.35;font-weight:700}h3{margin:.75rem 0 .5rem;color:var(--g);font-size:1rem;line-height:1.4;font-weight:700}p{margin:0 0 1rem}p:last-child{margin-bottom:0}
.education{background:var(--white)}.bite-photo-wrap{float:left;width:40%;max-width:26ch;margin:0 1.25rem .75rem 0}.bite-photo{display:block;width:100%;height:auto;aspect-ratio:16/9;object-fit:cover;border-radius:1.5rem}.photo-credit{display:block;width:100%;margin:.25rem 0 0;color:var(--black);text-align:center;font-size:.85rem;font-weight:400}.education-second{clear:both;padding-top:.5rem}
.layer-zone,.pairing-zone{background:var(--mint);border-color:var(--line)}.layer-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.layer-card{padding:1rem;border:.0625rem solid var(--line);border-radius:.75rem;background:var(--white)}.layer-number{margin:0 0 .5rem;color:var(--g);font-size:1rem;font-weight:700}.layer-card h3{margin:.25rem 0 .5rem;color:var(--g);font-size:1.2rem;line-height:1.35;font-weight:700}.layer-card p{margin:0;font-size:1rem}.layer-close{margin:1rem 0 0;padding:0;border:0;border-radius:0;background:transparent}
.comparison{background:var(--white)}.table-wrap{width:100%;max-width:100%;overflow-x:auto;border:.125rem solid var(--black);background:var(--white)}table{width:100%;min-width:42rem;border-collapse:collapse;color:var(--black);font-size:1rem;line-height:1.5}th,td{padding:.75rem;border:.0625rem solid var(--black);text-align:left;vertical-align:top}th{background:var(--white);color:var(--black);font-weight:700}
.barrier-zone{background:var(--beige);border-color:var(--line)}.card-zone-intro{margin:0 0 1rem}.product-grid{width:100%;max-width:100%;display:grid;grid-template-columns:repeat(3,minmax(0,14rem));justify-content:center;gap:1rem}
.product-card{display:flex;flex-direction:column;align-items:stretch;width:100%;max-width:14rem;margin-inline:auto;padding:1rem;border:.0625rem solid var(--line);border-radius:.75rem;background:var(--white)}
.product-window{display:flex;width:100%;aspect-ratio:16/10;align-items:center;justify-content:center;border:.125rem dashed var(--g);border-radius:1.5rem;background:var(--white);color:var(--black);text-align:center;font-size:1rem;font-weight:400;text-decoration:none}.product-window:hover{color:var(--b);text-decoration:underline}
.product-card h3{margin:.75rem 0 .5rem;color:var(--g);font-size:1rem;font-weight:700}.caption-line{margin:0 0 .5rem;color:var(--black);font-size:1rem;font-weight:400}.caption-line strong{color:var(--black);font-weight:700}
.product-cta{display:flex;align-items:center;justify-content:center;min-height:3rem;margin-top:auto;padding:.75rem 1rem;border:.0625rem solid var(--brown);border-radius:.5rem;background:var(--brown);color:var(--white);text-align:center;text-decoration:none;font-size:1rem;font-weight:700}.product-cta:hover{background:var(--brown);color:var(--white);text-decoration:underline}.card-spacer{height:.75rem;flex:1 0 .75rem}
.footer-zone{background:var(--g);color:var(--white);border:0;border-radius:.75rem;padding:2rem}.footer-zone h2,.footer-zone h3,.footer-zone p,.footer-zone .footer-nav span,.footer-zone .footer-nav a{color:var(--white)}.footer-zone a{color:var(--white);font-weight:700;text-decoration:underline}.footer-nav{display:flex;flex-direction:row;flex-wrap:nowrap;gap:1.5rem;margin:1.5rem 0;overflow-x:auto}.footer-nav a,.footer-nav span{font-size:1rem}.footer-nav span{font-weight:400}.copyright{margin:1rem 0 0;padding-top:1rem;border-top:.0625rem solid var(--white);color:var(--white);font-size:1rem}
@media(max-width:55rem){.desktop-nav{display:none}.menu-button{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto}.header-inner{gap:1rem}.product-grid{grid-template-columns:repeat(2,minmax(0,14rem))}}
@media(max-width:40rem){main,.wp-site-blocks main{width:calc(100% - 1rem);margin:1rem auto 2rem}.zone{padding:2rem;margin-bottom:1.5rem}.hero{padding:2rem}.mobile-nav{width:calc(100% - 1rem)}.layer-grid{grid-template-columns:minmax(0,1fr)}.product-grid{grid-template-columns:minmax(0,1fr)}.product-card{width:100%;max-width:14rem}.bite-photo-wrap{float:none;width:100%;max-width:none;margin:0 0 .75rem}.bite-photo{width:100%;aspect-ratio:16/9}.photo-credit{margin:0 0 1rem}.footer-nav{gap:1rem}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;animation:none!important;transition:none!important}}

